import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, Link } from 'react-router-dom';  // Importando Link
import './ProjetoList.css'; // Importe o CSS para aplicar os estilos

const ProjetoList = () => {
  const [projetos, setProjetos] = useState([]);
  const [loading, setLoading] = useState(true);
  const { clienteId } = useParams(); // Pegando o clienteId da URL

  useEffect(() => {
    const fetchProjetos = async () => {
      try {
        const response = await axios.get(`http://localhost:8080/clientes/${clienteId}/projetos`);
        setProjetos(response.data);
      } catch (err) {
        console.error("Erro ao carregar projetos", err);
      } finally {
        setLoading(false);
      }
    };

    fetchProjetos();
  }, [clienteId]);

  return (
    <div className="projeto-list">
      <h3>Projetos do Cliente</h3>
      {loading ? (
        <p>Carregando...</p>
      ) : (
        <div className="projetos-container">
          {projetos.length === 0 ? (
            <p>Não há projetos para este cliente.</p>
          ) : (
            projetos.map((projeto) => (
              <div className="projeto-card" key={projeto.id}>
                <h4>{projeto.nome}</h4>
                <p>{projeto.descricao}</p>
                <Link to={`/clientes/${clienteId}/projetos/${projeto.id}/atividades`} className="detalhes-link">
                  Ver Detalhes
                </Link>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default ProjetoList;
